create or replace function public._co_ok(_org uuid) returns boolean language sql stable security invoker set search_path=public as $$ select exists(select 1 from memberships m join organizations o on o.id=m.org_id where m.user_id=auth.uid() and m.org_id=_org and m.is_active and not m.branch_suspended and o.is_active and m.role in ('org_owner','principal','vice_principal','supervisor','teacher') and (m.school_id is null or exists(select 1 from schools s where s.id=m.school_id and s.org_id=_org and s.is_active)) and exists(select 1 from user_active_context c where c.user_id=auth.uid() and c.org_id=_org and c.role=m.role::text and c.school_id is not distinct from m.school_id)) $$;
revoke all on function public._co_ok(uuid) from public,anon; grant execute on function public._co_ok(uuid) to authenticated,service_role;
create table public.co_materials(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id), school_id uuid not null references public.schools(id), author uuid not null default auth.uid(), title text not null, description text not null default '', category text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
grant select,insert,update,delete on public.co_materials to authenticated; grant all on public.co_materials to service_role;
alter table public.co_materials enable row level security;
create policy co_materials_read on public.co_materials for select to authenticated using(_co_ok(org_id));
create policy co_materials_add on public.co_materials for insert to authenticated with check(_co_ok(org_id) and author=auth.uid() and school_org(school_id)=org_id);
create policy co_materials_edit on public.co_materials for update to authenticated using(_co_ok(org_id) and author=auth.uid()) with check(_co_ok(org_id) and author=auth.uid());
create policy co_materials_delete on public.co_materials for delete to authenticated using(_co_ok(org_id) and (author=auth.uid() or is_org_owner(org_id)));
create table public.co_reactions(material_id uuid not null references public.co_materials(id) on delete cascade, user_id uuid not null default auth.uid(), emoji text not null, created_at timestamptz not null default now(), primary key(material_id,user_id));
grant select,insert,update,delete on public.co_reactions to authenticated; grant all on public.co_reactions to service_role;
alter table public.co_reactions enable row level security;
create policy co_reactions_read on public.co_reactions for select to authenticated using(exists(select 1 from co_materials where id=material_id));
create policy co_reactions_add on public.co_reactions for insert to authenticated with check(user_id=auth.uid() and emoji in ('👍','❤️','👏','💡','🎉') and exists(select 1 from co_materials where id=material_id));
create policy co_reactions_edit on public.co_reactions for update to authenticated using(user_id=auth.uid() and exists(select 1 from co_materials where id=material_id)) with check(user_id=auth.uid() and emoji in ('👍','❤️','👏','💡','🎉') and exists(select 1 from co_materials where id=material_id));
create policy co_reactions_delete on public.co_reactions for delete to authenticated using(user_id=auth.uid() and exists(select 1 from co_materials where id=material_id));
create or replace function public._co_material_guard() returns trigger language plpgsql set search_path=public as $$ begin if new.category not in ('activities','teaching','worksheets','notes','summaries','courses') or length(trim(new.title))<2 or length(new.title)>200 or length(new.description)>10000 then raise exception 'بيانات المادة غير صالحة'; end if; if tg_op='UPDATE' and (new.id,new.org_id,new.school_id,new.author,new.created_at) is distinct from (old.id,old.org_id,old.school_id,old.author,old.created_at) then raise exception 'لا يسمح بنقل ملكية أو نطاق المادة'; end if; new.updated_at:=now(); return new; end $$;
create trigger co_material_guard before insert or update on public.co_materials for each row execute function public._co_material_guard();
revoke all on function public._co_material_guard() from public,anon,authenticated;
-- Keep the previous shared access/send logic for every non-community conversation.
alter function public.conv_access_ok(uuid) rename to _conv_access_before_co;
create or replace function public.conv_access_ok(_conv uuid) returns boolean language sql stable security definer set search_path=public as $$ select _conv_access_before_co(_conv) and not exists(select 1 from conversations c where c.id=_conv and c.dedupe_key like 'co:%' and not _co_ok(c.org_id)) $$;
revoke all on function public.conv_access_ok(uuid) from public,anon; grant execute on function public.conv_access_ok(uuid) to authenticated,service_role;
alter function public.conv_send_block(uuid) rename to _conv_send_before_co;
create or replace function public.conv_send_block(_conv uuid) returns text language plpgsql stable security definer set search_path=public as $$ declare o uuid; begin select org_id into o from conversations where id=_conv and dedupe_key like 'co:%'; if o is not null and not _co_ok(o) then return 'غير مصرح بالمجتمع المهني'; end if; return _conv_send_before_co(_conv); end $$;
revoke all on function public.conv_send_block(uuid) from public,anon; grant execute on function public.conv_send_block(uuid) to authenticated,service_role;
create or replace function public.co_community(_org uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare c conversations; u uuid; begin if not _co_ok(_org) then raise exception 'غير مصرح'; end if; perform pg_advisory_xact_lock(hashtext('co:'||_org)); select * into c from conversations where dedupe_key='co:'||_org; if c.id is null then insert into conversations(org_id,kind,group_type,title,membership_mode,history_policy,dedupe_key) values(_org,'group','custom','المجتمع المهني','derived','full','co:'||_org) returning * into c; end if; for u in select distinct m.user_id from memberships m join organizations o on o.id=m.org_id where m.org_id=_org and m.is_active and not m.branch_suspended and o.is_active and m.role in ('org_owner','principal','vice_principal','supervisor','teacher') and (m.school_id is null or exists(select 1 from schools s where s.id=m.school_id and s.is_active and s.org_id=_org)) loop perform _add_member(c.id,u,'member','derived',c.created_at); end loop; return to_jsonb(c); end $$;
revoke all on function public.co_community(uuid) from public,anon; grant execute on function public.co_community(uuid) to authenticated,service_role;
-- Library files use the same private bucket and source-derived reader.
alter table public.files drop constraint files_source_type_check;
alter table public.files add constraint files_source_type_check check(source_type=any(array['post','message','message_pending','circular','cleanup_due','homework','submission','feedback','pickup','admin','support','support_pending','pc','maint','hr','notice','org_doc','org_doc_pending','evt_item','evt_app','evt_pending','co_material']));
alter function public.can_read_file(uuid) rename to _can_read_file_before_co;
create or replace function public.can_read_file(_file uuid) returns boolean language sql stable security definer set search_path=public as $$ select _can_read_file_before_co(_file) or exists(select 1 from files f join co_materials m on m.id=f.source_id where f.id=_file and f.source_type='co_material' and f.school_id=m.school_id and _co_ok(m.org_id)) $$;
revoke all on function public.can_read_file(uuid) from public,anon; grant execute on function public.can_read_file(uuid) to authenticated,service_role;
create or replace function public.co_add_file(_material uuid,_name text,_mime text,_size bigint) returns jsonb language plpgsql security definer set search_path=public as $$ declare m co_materials; p record; f files; fid uuid:=gen_random_uuid(); begin select * into m from co_materials where id=_material; if m.id is null or not _co_ok(m.org_id) or m.author<>auth.uid() then raise exception 'غير مصرح'; end if; select * into p from _file_policy(m.school_id); if not _mime=any(p.allowed_types) or _size<=0 or _size>p.max_bytes then raise exception 'نوع أو حجم الملف غير مسموح'; end if; insert into files(id,school_id,storage_path,name,mime_type,size_bytes,source_type,source_id) values(fid,m.school_id,m.school_id||'/co/'||m.id||'/'||fid,left(_name,200),_mime,_size,'co_material',m.id) returning * into f; return to_jsonb(f); end $$;
create or replace function public.co_remove_file(_id uuid) returns void language plpgsql security definer set search_path=public as $$ declare f files; m co_materials; begin select * into f from files where id=_id and source_type='co_material'; select * into m from co_materials where id=f.source_id; if m.id is null or not _co_ok(m.org_id) or (m.author<>auth.uid() and not is_org_owner(m.org_id)) then raise exception 'غير مصرح'; end if; update files set source_type='cleanup_due' where id=f.id; end $$;
revoke all on function public.co_add_file(uuid,text,text,bigint),public.co_remove_file(uuid) from public,anon; grant execute on function public.co_add_file(uuid,text,text,bigint),public.co_remove_file(uuid) to authenticated,service_role;